types:
TYPE ST_Recipe :
STRUCT
    recipeID : INT;
    totalRatio : REAL;
    temperature : REAL;
END_STRUCT
END_TYPE

declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    recipe : ARRAY[1..8] OF ST_Recipe;
    selSlot : INT;
    loadCmd : BOOL;
    running : BOOL;
END_VAR
VAR_OUTPUT
    valid : BOOL;
    loadedID : INT;
END_VAR
VAR
    loadPrev : BOOL;
    loadEdge : BOOL;
    ok : BOOL;
    slotOK : BOOL;
    selectedRecipe : ST_Recipe;
END_VAR

implementation:
loadEdge := loadCmd AND NOT loadPrev;
loadPrev := loadCmd;

IF loadEdge AND NOT running THEN
    slotOK := (selSlot >= 1) AND (selSlot <= 8);

    valid := FALSE;
    loadedID := 0;
    IF slotOK THEN
        selectedRecipe := recipe[selSlot];
        ok := selectedRecipe.recipeID <> 0;
        IF selectedRecipe.totalRatio < 99.0 OR selectedRecipe.totalRatio > 101.0 THEN
            ok := FALSE;
        END_IF
        IF selectedRecipe.temperature < 30.0 OR selectedRecipe.temperature > 180.0 THEN
            ok := FALSE;
        END_IF
        valid := ok;
        IF ok THEN
            loadedID := selectedRecipe.recipeID;
        END_IF
    END_IF
END_IF
